insert into public.education_lesson_contents (lesson_id, goal, explanation, example, summary, sources, reviewed_on) values
('e3ab37b6-199a-53a7-8125-60fe1916aadf', 'Diferenciar poupar, investir e a caderneta de poupança.', 'Poupar é separar parte do dinheiro de hoje para o futuro. Investir é aplicar esse dinheiro em produtos financeiros buscando retorno, aceitando algum nível de risco. A caderneta de poupança é apenas um desses produtos: não é sinônimo de poupar.', 'Bia recebe R$ 200 de mesada e separa R$ 30 todo mês. Ela já está poupando, mesmo antes de escolher onde deixar esse dinheiro.', array['Poupar é um hábito; investir é uma escolha de aplicação.', 'A caderneta é um produto, não sinônimo de poupar.', 'Todo produto tem risco, liquidez e rendimento próprios.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}, {"n": "Portal do Investidor (CVM)", "u": "https://www.investidor.gov.br"}]'::jsonb, '2026-11-01'::date),
('eb7c1021-7199-51ac-a236-4bb82130a9cd', 'Entender para que serve a reserva de emergência e quanto ela deve cobrir.', 'Reserva de emergência é dinheiro guardado para imprevistos, como um conserto urgente ou uma perda de renda. Ela precisa estar disponível rápido (liquidez) e com baixo risco de perda. Uma referência comum é cobrir alguns meses de gastos essenciais — só os essenciais, sem lazer ou desejos.', 'Se os gastos essenciais de Lucas são R$ 1.200 por mês e ele quer uma reserva de 3 meses, o alvo é R$ 3.600.', array['Reserva é para imprevistos, não para desejos.', 'Liquidez e segurança vêm antes de rentabilidade.', 'Uma referência: alguns meses de gastos essenciais.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('fa3048b1-b929-5a46-92ec-a50d0d76cefc', 'Criar o hábito de guardar mesmo com valores pequenos.', 'Consistência vale mais do que valor. Separar um valor possível assim que o dinheiro entra, antes de gastar, é mais eficaz do que tentar guardar o que sobra. Uma porcentagem fixa da renda ajuda o valor guardado a crescer junto com ela.', 'Guardar R$ 25 por semana parece pouco, mas em 12 semanas soma R$ 300.', array['Pequenos valores constantes somam bastante.', 'Separe primeiro, gaste depois.', 'Revise o valor quando sua renda mudar.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('e40b0a29-a981-5d8a-a3fe-69a186ed86ee', 'Registrar e classificar receitas e despesas.', 'Receita é todo dinheiro que entra. Despesa é todo dinheiro que sai. Registrar as duas mostra o resultado do mês: receitas menos despesas. Gastos fixos se repetem com valor parecido; variáveis mudam de mês a mês. A parcela de uma compra também é despesa do mês em que é paga.', 'Em setembro, Caio recebeu R$ 300 de mesada e vendeu bolos por R$ 120. Gastou R$ 260 com lanche e transporte. Resultado: 420 − 260 = R$ 160.', array['Receita entra, despesa sai.', 'Resultado do mês = receitas − despesas.', 'Fixos são previsíveis; variáveis mudam.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('b741a9eb-c48c-5e77-9f00-b41df5fa1cac', 'Separar necessidades de desejos e reconhecer compras por impulso.', 'Necessidades são gastos essenciais, como alimentação, transporte para estudar e material escolar. Desejos trazem prazer, mas podem esperar. Compra por impulso é a que acontece sem planejamento, geralmente por emoção ou promoção. Parcelar ''sem juros'' também merece conta: compare o total parcelado com o preço à vista.', 'Você entra na loja para comprar um caderno e sai com um fone em promoção. O caderno era necessidade; o fone foi compra por impulso.', array['Necessidade é essencial; desejo pode esperar.', 'Impulso = sem planejamento, por emoção ou pressa.', 'Esperar 24 horas ajuda a decidir.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('1fa3fab2-9e77-562b-a40a-8676296fe28f', 'Montar uma rotina simples de revisão mensal.', 'Uma boa rotina tem três passos: registrar, categorizar e revisar. Comparar o que você planejou com o que gastou, categoria por categoria, mostra onde ajustar. O melhor método é o que você consegue manter.', 'No fim do mês, Rita vê que gastou R$ 150 com lazer, mas tinha planejado R$ 100. No mês seguinte, ela reduz as saídas ou aumenta o limite de forma consciente.', array['Registrar, categorizar e revisar.', 'Compare planejado e realizado.', 'O melhor método é o que você mantém.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('eb687473-3525-5bda-bfc2-98f898d6f9b0', 'Transformar um objetivo em valor, prazo e contribuição mensal.', 'Uma meta clara tem objetivo, valor-alvo e prazo. Dividir o que falta pelos meses em que você realmente vai conseguir guardar dá uma referência de quanto separar por mês. Em geral, curto prazo é até 1 ano, médio prazo de 1 a 5 anos e longo prazo acima disso.', 'Para um notebook de R$ 3.000, já com R$ 900 guardados, faltam R$ 2.100. Em 7 meses, isso dá R$ 300 por mês.', array['Meta = objetivo + valor + prazo.', 'Falta ÷ meses em que você guarda = valor mensal.', 'Prazos: curto, médio e longo.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('813ffd4b-80b1-5b80-9f15-f21c5fae25d1', 'Montar um orçamento fictício usando a regra 50/30/20 como ponto de partida.', 'A regra 50/30/20 sugere dividir a renda em 50% para necessidades, 30% para desejos e 20% para poupança e metas. É um exemplo adaptável: cada realidade pede ajustes. Quando as necessidades passam de 50%, o espaço para desejos diminui se você quiser manter a poupança. Revise o plano sempre que a renda ou os objetivos mudarem. Aqui você usa só valores fictícios.', 'Com R$ 1.000 fictícios: R$ 500 em necessidades, R$ 300 em desejos e R$ 200 para poupar.', array['50/30/20 é um exemplo, não uma regra fixa.', 'O orçamento precisa fechar 100% da renda.', 'Revise sempre que algo mudar.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('6817bcb2-df26-5df2-beb9-3b4933a90c94', 'Entender o que é o Tesouro Direto e o que muda entre os títulos.', 'O Tesouro Direto é um programa em que o governo federal vende títulos públicos a pessoas físicas. Há títulos com prazos e formas de remuneração diferentes: o Tesouro Selic acompanha a taxa básica de juros e oscila pouco; o prefixado tem a taxa combinada na compra; o IPCA+ paga a inflação mais uma taxa. Consulte preços e regras atuais no site oficial.', 'Ao comprar um título, você empresta dinheiro ao governo e recebe de volta com remuneração no prazo combinado.', array['Títulos públicos são emitidos pelo governo federal.', 'Selic, prefixado e IPCA+ remuneram de formas diferentes.', 'Consulte regras atuais no site oficial.']::text[], '[{"n": "Tesouro Direto", "u": "https://www.tesourodireto.com.br"}, {"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('0fd3f26c-2c29-58e6-b881-26f3d2672209', 'Relacionar Selic, juros e inflação.', 'A Selic é a taxa básica de juros da economia e é definida periodicamente pelo Copom, do Banco Central. Juros são o preço do dinheiro no tempo, e os juros compostos incidem sobre o valor já acrescido. Inflação é o aumento geral dos preços, que reduz o poder de compra. Uma aproximação útil: ganho real ≈ rendimento − inflação. Consulte a taxa vigente no Banco Central.', 'Se um lanche custava R$ 10 e hoje custa R$ 11, houve inflação: o mesmo dinheiro compra menos.', array['A Selic é a taxa básica e é definida pelo Copom.', 'Juros compostos incidem sobre o valor já acrescido.', 'Ganho real ≈ rendimento − inflação.']::text[], '[{"n": "Banco Central do Brasil — Cidadania Financeira", "u": "https://www.bcb.gov.br/cidadaniafinanceira"}]'::jsonb, '2026-11-01'::date),
('6e9b403d-d0c8-5615-8104-7dbae94d0485', 'Compreender risco e retorno nos fundos imobiliários.', 'Fundos imobiliários reúnem dinheiro de vários investidores para aplicar em ativos do setor imobiliário. As cotas são negociadas em bolsa e o preço oscila. Rendimentos não são garantidos: dependem do desempenho do fundo, por exemplo de imóveis alugados ou vagos. Fundos imobiliários não têm a garantia do FGC. O resultado de quem investe soma os rendimentos recebidos e a variação do preço da cota.', 'Uma cota comprada a R$ 100 pode valer R$ 92 ou R$ 108 dias depois, e o rendimento mensal também pode variar.', array['Cotas oscilam e rendimentos variam.', 'Resultado = rendimentos + variação da cota.', 'Nada de lucro garantido.']::text[], '[{"n": "Portal do Investidor (CVM)", "u": "https://www.investidor.gov.br"}]'::jsonb, '2026-11-01'::date),
('4c9aba9b-98b2-5075-8c25-53fcdb7ccc0a', 'Comparar liquidez, risco e diversificação em produtos básicos, como o CDB.', 'O CDB é um título emitido por bancos para captar dinheiro. Compare sempre risco, retorno esperado, liquidez, custos e tributação. Diversificar é não concentrar todo o dinheiro em um só investimento: o resultado total é a soma do que cada parte rendeu ou perdeu. Nenhum investimento deve ser tratado como lucro garantido, e promessas de retorno alto ''sem risco'' são sinal de golpe.', 'Marta deixa a reserva de emergência em algo de fácil resgate e coloca um objetivo distante em um produto de prazo maior.', array['CDB é emitido por bancos.', 'Compare liquidez, risco, custos e tributação.', 'Diversificar reduz a dependência de um só produto.']::text[], '[{"n": "Portal do Investidor (CVM)", "u": "https://www.investidor.gov.br"}, {"n": "Tesouro Direto", "u": "https://www.tesourodireto.com.br"}]'::jsonb, '2026-11-01'::date)
insert into public.education_activities (id, lesson_id, position, kind, prompt, public_data) values
('afeeefce-155f-5362-a69b-b1bf90b43e9b'::uuid, 'e3ab37b6-199a-53a7-8125-60fe1916aadf'::uuid, 0, 'quiz', 'Ana guarda R$ 50 por mês numa gaveta. Beto aplica R$ 50 por mês num CDB. Qual afirmação é correta?', '{"opts": ["Só Beto está poupando, porque aplicou o dinheiro", "Os dois estão poupando, mas só Beto está investindo", "Os dois estão investindo", "Nenhum dos dois está poupando, porque os valores são pequenos"]}'::jsonb),
('e12bd45b-fff1-5b35-b689-9ee509b9e145'::uuid, 'e3ab37b6-199a-53a7-8125-60fe1916aadf'::uuid, 1, 'classify', 'Classifique cada situação:', '{"buckets": ["Hábito de poupar", "Produto financeiro"], "items": ["Separar 10% da mesada assim que recebe", "Caderneta de poupança", "Tesouro Selic", "Deixar de pedir delivery e guardar a diferença", "CDB", "Guardar o troco do lanche num cofrinho"]}'::jsonb),
('ad476c6b-5e37-570f-8f2e-503cb33358cb'::uuid, 'e3ab37b6-199a-53a7-8125-60fe1916aadf'::uuid, 2, 'multi', 'Quais afirmações são verdadeiras? Marque todas.', '{"opts": ["A caderneta é um produto financeiro, não sinônimo de poupar", "A caderneta é o único jeito seguro de poupar", "Todo produto tem rendimento, liquidez e risco próprios", "O rendimento da caderneta nunca fica abaixo da inflação", "Guardar dinheiro sem aplicar também é poupar"]}'::jsonb),
('3b5c9fc9-2826-50af-9461-7f7110242cd3'::uuid, 'eb7c1021-7199-51ac-a236-4bb82130a9cd'::uuid, 0, 'multi', 'Quais situações justificam usar a reserva de emergência? Marque todas.', '{"opts": ["Conserto urgente do celular que você usa para estudar", "Promoção de um jogo novo", "Perda temporária de renda", "Ingresso de show", "Remédio que não estava previsto", "Trocar de celular porque saiu um modelo novo"]}'::jsonb),
('f89c0b4f-1244-56ac-b83f-ef8af9d543c3'::uuid, 'eb7c1021-7199-51ac-a236-4bb82130a9cd'::uuid, 1, 'calc', 'Os gastos de Lucas por mês: aluguel R$ 700, alimentação R$ 450, transporte R$ 150, contas R$ 200 e lazer R$ 300. Qual o valor de uma reserva de 3 meses, considerando só os gastos essenciais?', '{"unit": "R$"}'::jsonb),
('517af18e-13b9-50ff-bb77-cf6665a01781'::uuid, 'eb7c1021-7199-51ac-a236-4bb82130a9cd'::uuid, 2, 'calc', 'Lucas já tem R$ 1.800 guardados e consegue separar R$ 300 por mês. Em quantos meses ele completa a reserva de R$ 4.500?', '{"unit": "meses"}'::jsonb),
('719c9496-1d78-5c1e-b1d7-76b1cc9b774f'::uuid, 'eb7c1021-7199-51ac-a236-4bb82130a9cd'::uuid, 3, 'quiz', 'Onde faz mais sentido deixar a reserva de emergência?', '{"opts": ["Em ações de uma única empresa, que podem render mais", "Em um investimento de baixo risco e resgate rápido, como Tesouro Selic ou CDB com liquidez diária", "Em um título que só pode ser resgatado daqui a 5 anos", "Emprestado a um amigo, que prometeu devolver com juros"]}'::jsonb),
('e069aa5e-80bf-5a56-96bf-69a35e4c1029'::uuid, 'fa3048b1-b929-5a46-92ec-a50d0d76cefc'::uuid, 0, 'calc', 'Júlia recebe R$ 800 por mês e guarda 15% assim que o dinheiro entra. Quanto ela terá separado em 12 meses, sem contar rendimentos?', '{"unit": "R$"}'::jsonb),
('bcab4376-dce7-5d70-87b5-1277ac71ed39'::uuid, 'fa3048b1-b929-5a46-92ec-a50d0d76cefc'::uuid, 1, 'calc', 'Pedro guarda R$ 20 por semana. Se passar a guardar R$ 35 por semana, quanto ele guarda A MAIS em 12 semanas?', '{"unit": "R$"}'::jsonb),
('79e5fa89-23b4-5e49-8033-153641cb0214'::uuid, 'fa3048b1-b929-5a46-92ec-a50d0d76cefc'::uuid, 2, 'quiz', 'Duas estratégias por 6 meses. A: guardar R$ 100 no fim do mês, se sobrar (nos últimos 6 meses, sobrou em só 2). B: separar R$ 60 todo mês no dia em que recebe. Qual guarda mais?', '{"opts": ["A, porque o valor mensal é maior", "B: guarda R$ 360 contra R$ 200, porque separar primeiro não depende de sobrar", "As duas guardam o mesmo valor", "A, porque guardar no fim do mês evita faltar dinheiro"]}'::jsonb),
('6333e127-3074-50e9-a078-700c306afb80'::uuid, 'fa3048b1-b929-5a46-92ec-a50d0d76cefc'::uuid, 3, 'classify', 'Classifique cada atitude:', '{"buckets": ["Ajuda a manter o hábito", "Atrapalha o hábito"], "items": ["Transferência automática no dia do pagamento", "Guardar só o que sobrar no fim do mês", "Ajustar o valor quando a renda muda", "Esperar juntar um valor alto para começar", "Ter uma meta com valor e prazo", "Usar o dinheiro guardado em compras por impulso"]}'::jsonb),
('52bbe383-ffc3-5e79-bc8d-b412d0efc8f2'::uuid, 'e40b0a29-a981-5d8a-a3fe-69a186ed86ee'::uuid, 0, 'classify', 'Classifique cada item:', '{"buckets": ["Receita", "Despesa"], "items": ["Mesada", "Passagem de ônibus", "Venda de bolo", "Assinatura de streaming", "Dinheiro recebido de presente", "Parcela do celular"]}'::jsonb),
('59045f56-a9d7-5d95-b886-d44243867499'::uuid, 'e40b0a29-a981-5d8a-a3fe-69a186ed86ee'::uuid, 1, 'calc', 'Em outubro, Caio recebeu R$ 300 de mesada e R$ 180 vendendo bolos. Gastou R$ 120 com lanche, R$ 90 com transporte e pagou R$ 150 da parcela de uma compra. Qual foi o resultado do mês?', '{"unit": "R$"}'::jsonb),
('ea62b563-8d22-5f0f-96e1-dc2cda778851'::uuid, 'e40b0a29-a981-5d8a-a3fe-69a186ed86ee'::uuid, 2, 'classify', 'Classifique cada gasto:', '{"buckets": ["Gasto fixo", "Gasto variável"], "items": ["Mensalidade do curso de inglês", "Lanches na escola", "Assinatura de streaming", "Cinema com amigos", "Plano de celular", "Presentes de aniversário"]}'::jsonb),
('09db1230-2dce-597c-99f9-208d4f696396'::uuid, 'b741a9eb-c48c-5e77-9f00-b41df5fa1cac'::uuid, 0, 'classify', 'Classifique cada gasto:', '{"buckets": ["Necessidade", "Desejo"], "items": ["Material escolar", "Passagem para ir à escola", "Jogo novo em lançamento", "Tênis de marca só por moda", "Conta de luz", "Trocar um celular que ainda funciona bem"]}'::jsonb),
('060f378f-4602-56c6-afbe-6b0904c5e2f7'::uuid, 'b741a9eb-c48c-5e77-9f00-b41df5fa1cac'::uuid, 1, 'multi', 'Quais sinais indicam uma compra por impulso? Marque todos.', '{"opts": ["Estava na lista de compras planejada", "Comprei com pressa, por causa de uma promoção ''só hoje''", "Comprei depois de comparar preços por alguns dias", "Comprei para me sentir melhor na hora, sem pensar", "Parcelei sem somar as parcelas que já tinha no mês", "Esperei 24 horas e ainda achava a compra necessária"]}'::jsonb),
('2166148d-bca5-589d-9212-6d1c2f035db1'::uuid, 'b741a9eb-c48c-5e77-9f00-b41df5fa1cac'::uuid, 2, 'calc', 'Um fone custa R$ 200 à vista ou 10× de R$ 24 ''sem juros'' na promoção. Quanto você paga A MAIS escolhendo o parcelado?', '{"unit": "R$"}'::jsonb),
('179a914a-87f7-5188-a0da-b79bc1b5c061'::uuid, 'b741a9eb-c48c-5e77-9f00-b41df5fa1cac'::uuid, 3, 'quiz', 'Bruna tem R$ 100 livres no mês. Viu um tênis de R$ 90 em promoção que acaba hoje, mas a mochila da escola rasgou e uma nova custa R$ 70. Qual decisão segue melhor o que você aprendeu?', '{"opts": ["Comprar o tênis, porque a promoção acaba hoje", "Comprar a mochila e planejar o tênis para quando couber no orçamento", "Parcelar o tênis e a mochila juntos para levar os dois", "Não comprar nada, porque todo gasto é ruim"]}'::jsonb),
('75432aa2-175b-58c0-916d-21279e6c180f'::uuid, '1fa3fab2-9e77-562b-a40a-8676296fe28f'::uuid, 0, 'classify', 'Em qual passo da rotina está cada ação?', '{"buckets": ["Registrar", "Categorizar", "Revisar"], "items": ["Anotar o lanche no app logo depois de pagar", "Marcar a compra do caderno como Educação", "Comparar o gasto de lazer com o planejado no fim do mês", "Lançar o valor da passagem de ônibus", "Separar os gastos do mês entre fixos e variáveis", "Decidir reduzir o delivery no mês seguinte"]}'::jsonb),
('4015f9de-3893-5307-ac68-9309f85d80e1'::uuid, '1fa3fab2-9e77-562b-a40a-8676296fe28f'::uuid, 1, 'calc', 'Rita planejou: lazer R$ 100, transporte R$ 120 e alimentação R$ 250. Gastou: lazer R$ 150, transporte R$ 110 e alimentação R$ 270. Somando as três categorias, quanto ela passou do total planejado?', '{"unit": "R$"}'::jsonb),
('3b33925d-a504-5a9a-976d-6bcb3db22f94'::uuid, '1fa3fab2-9e77-562b-a40a-8676296fe28f'::uuid, 2, 'quiz', 'Pelos números de Rita, qual ajuste é mais coerente para o próximo mês?', '{"opts": ["Cortar transporte, porque foi a categoria que mais estourou", "Rever o lazer, que passou R$ 50 do planejado e explica a maior parte do excesso", "Não mudar nada, porque R$ 60 é pouco", "Parar de registrar, porque os números só trazem preocupação"]}'::jsonb),
('5c3f5a63-6691-5345-95f5-e9e136a94177'::uuid, '1fa3fab2-9e77-562b-a40a-8676296fe28f'::uuid, 3, 'calc', 'Rita recebe R$ 1.000 por mês. Com as despesas de R$ 530, que porcentagem da renda sobrou?', '{"unit": "%"}'::jsonb),
('56a32696-fd0c-566c-867d-d3d1f107bfc4'::uuid, 'eb687473-3525-5bda-bfc2-98f898d6f9b0'::uuid, 0, 'calc', 'Meta de R$ 3.000 com R$ 900 já reservados. Quanto falta?', '{"unit": "R$"}'::jsonb),
('474397f3-5671-5185-abeb-4a39c0e822f7'::uuid, 'eb687473-3525-5bda-bfc2-98f898d6f9b0'::uuid, 1, 'calc', 'Faltam R$ 2.100 e o prazo é de 7 meses, mas Paulo sabe que em um desses meses não vai conseguir guardar nada. Quanto ele precisa guardar em cada um dos outros meses?', '{"unit": "R$"}'::jsonb),
('89367997-3379-521c-952e-63468a8f3d59'::uuid, 'eb687473-3525-5bda-bfc2-98f898d6f9b0'::uuid, 2, 'classify', 'Classifique o prazo de cada objetivo:', '{"buckets": ["Curto prazo", "Médio prazo", "Longo prazo"], "items": ["Presente de aniversário daqui a 2 meses", "Notebook daqui a 2 anos", "Entrada da faculdade daqui a 8 anos", "Viagem de formatura daqui a 3 anos", "Passeio no mês que vem"]}'::jsonb),
('82c6e5d5-afd3-500a-b6ca-bcd96ce2da26'::uuid, 'eb687473-3525-5bda-bfc2-98f898d6f9b0'::uuid, 3, 'quiz', 'Qual destas é uma meta bem definida?', '{"opts": ["Quero guardar dinheiro", "Quero juntar R$ 1.200 para um curso até dezembro, guardando R$ 150 por mês", "Quero ficar rico", "Vou guardar quando sobrar"]}'::jsonb),
('08d6dd3f-932e-503f-85df-e494b748bf45'::uuid, '813ffd4b-80b1-5b80-9f15-f21c5fae25d1'::uuid, 0, 'budget', 'Distribua a renda fictícia de R$ 1.200. Regras: no mínimo 15% para poupança, no máximo 55% para necessidades e no máximo 30% para desejos. A soma precisa fechar 100%.', '{"cats": ["Necessidades", "Desejos", "Poupança"], "total": "R$ 1.200,00 (fictício)"}'::jsonb),
('cb06908d-860f-52d0-a151-45a1e648e57c'::uuid, '813ffd4b-80b1-5b80-9f15-f21c5fae25d1'::uuid, 1, 'calc', 'A renda de Maria é R$ 1.200 e as necessidades dela somam R$ 720. Se ela mantiver 20% da renda para poupança, quanto sobra por mês para desejos?', '{"unit": "R$"}'::jsonb),
('b93f423b-02f5-556d-a80c-0dd8173f7dd8'::uuid, '813ffd4b-80b1-5b80-9f15-f21c5fae25d1'::uuid, 2, 'quiz', 'Pelos números de Maria, que fatia da renda as necessidades ocupam e o que isso indica?', '{"opts": ["40%: abaixo da referência de 50%", "60%: acima da referência de 50%, então vale rever gastos essenciais ou aceitar menos desejos", "50%: exatamente na referência", "72%: o orçamento é impossível"]}'::jsonb),
('a55cf097-5624-5fef-bf18-73669242829b'::uuid, '6817bcb2-df26-5df2-beb9-3b4933a90c94'::uuid, 0, 'quiz', 'Quem emite os títulos do Tesouro Direto?', '{"opts": ["Um banco privado", "O governo federal", "A bolsa de valores", "O Procon"]}'::jsonb),
('1cc22d36-c880-5133-b9b2-5ab10568ebcf'::uuid, '6817bcb2-df26-5df2-beb9-3b4933a90c94'::uuid, 1, 'classify', 'Relacione cada característica ao título:', '{"buckets": ["Tesouro Selic", "Tesouro Prefixado", "Tesouro IPCA+"], "items": ["Rende de acordo com a taxa básica de juros", "Você sabe a taxa exata no momento da compra", "Paga a inflação do período mais uma taxa", "Costuma ser usado para reserva de emergência, por oscilar pouco", "Protege o poder de compra em objetivos longos"]}'::jsonb),
('26791cfb-5a5e-55e9-b74b-5d67eb531c3f'::uuid, '6817bcb2-df26-5df2-beb9-3b4933a90c94'::uuid, 2, 'quiz', 'Vender um título prefixado antes do vencimento...', '{"opts": ["Sempre garante o valor combinado na compra", "Pode render menos ou mais, conforme o preço do título no dia da venda", "É proibido", "Não tem nenhum custo nem imposto"]}'::jsonb),
('0f3cabe3-313d-5bc1-9895-aec0fd7c6f65'::uuid, '0fd3f26c-2c29-58e6-b881-26f3d2672209'::uuid, 0, 'quiz', 'Quem define a meta da Selic?', '{"opts": ["O Copom, do Banco Central", "O Tesouro Direto", "A CVM", "Cada banco"]}'::jsonb),
('3ae57711-5c56-5c14-bcca-b1dcd2a7fcad'::uuid, '0fd3f26c-2c29-58e6-b881-26f3d2672209'::uuid, 1, 'calc', 'R$ 100 rendem 10% ao ano, com juros compostos, por 2 anos. Qual o total?', '{"unit": "R$"}'::jsonb),
('d26572e5-d868-5c12-ae5c-467347b1a1a0'::uuid, '0fd3f26c-2c29-58e6-b881-26f3d2672209'::uuid, 2, 'calc', 'Um investimento rendeu 10% em um ano e a inflação do período foi 4%. Pela aproximação rendimento − inflação, qual foi o ganho real, em %?', '{"unit": "%"}'::jsonb),
('3e404291-53f5-50e2-bf51-25228b8ebba4'::uuid, '0fd3f26c-2c29-58e6-b881-26f3d2672209'::uuid, 3, 'quiz', 'Um produto rendeu 5% no ano e a inflação foi 6%. O que aconteceu com quem investiu?', '{"opts": ["Ganhou poder de compra, porque o saldo aumentou", "Perdeu cerca de 1% de poder de compra, mesmo com saldo maior", "Ficou exatamente igual", "Perdeu 5% do dinheiro"]}'::jsonb),
('f87652e7-2781-576d-8124-eeaf90dac7b8'::uuid, '6e9b403d-d0c8-5615-8104-7dbae94d0485'::uuid, 0, 'quiz', 'Sobre fundos imobiliários, é correto dizer:', '{"opts": ["O rendimento é garantido", "As cotas podem oscilar e o rendimento pode variar", "Não têm risco", "Só grandes investidores podem comprar"]}'::jsonb),
('5e73c233-edf3-53eb-8ea1-b35d50806e75'::uuid, '6e9b403d-d0c8-5615-8104-7dbae94d0485'::uuid, 1, 'multi', 'Quais riscos existem em fundos imobiliários? Marque todos.', '{"opts": ["Queda no preço da cota", "Imóveis vagos reduzirem os rendimentos", "Perder a garantia do FGC, que cobre o valor investido", "Não conseguir vender a cota rápido pelo preço desejado", "Receber um rendimento fixo menor que o combinado na compra"]}'::jsonb),
('f77ad52a-2434-5f76-8836-5d52532d5b57'::uuid, '6e9b403d-d0c8-5615-8104-7dbae94d0485'::uuid, 2, 'calc', 'Uma cota foi comprada por R$ 100, pagou R$ 0,80 de rendimento por mês durante 12 meses e no fim do ano valia R$ 92. Somando rendimentos e variação da cota, qual foi o resultado, em reais, por cota?', '{"unit": "R$"}'::jsonb),
('bc1ec29f-9974-5781-8587-8bf301404e97'::uuid, '6e9b403d-d0c8-5615-8104-7dbae94d0485'::uuid, 3, 'quiz', 'Que relação costuma existir entre risco e retorno?', '{"opts": ["Maior retorno esperado costuma vir com maior risco", "Não há relação", "Menor risco sempre rende mais", "O retorno é sempre garantido"]}'::jsonb),
('ba892358-4119-52dd-9b2f-47590773c7b6'::uuid, '4c9aba9b-98b2-5075-8c25-53fcdb7ccc0a'::uuid, 0, 'multi', 'Quais cuidados ajudam a avaliar um investimento? Marque todos.', '{"opts": ["Comparar liquidez e prazo", "Confiar em promessa de lucro garantido", "Conferir custos e tributação", "Diversificar", "Colocar tudo no produto que mais rendeu no ano passado", "Verificar se a instituição é autorizada pela CVM ou pelo Banco Central"]}'::jsonb),
('0b61b54b-6f83-5103-b902-1541d51ab8e5'::uuid, '4c9aba9b-98b2-5075-8c25-53fcdb7ccc0a'::uuid, 1, 'classify', 'Para cada objetivo, qual tipo de aplicação combina mais?', '{"buckets": ["Resgate rápido e baixo risco", "Prazo longo, pode oscilar"], "items": ["Reserva de emergência", "Aposentadoria daqui a 30 anos", "Conserto que pode surgir a qualquer momento", "Entrada de um imóvel daqui a 10 anos", "Viagem do mês que vem"]}'::jsonb),
('9b8e9045-1d5e-5068-9c8b-207aa6aafbc4'::uuid, '4c9aba9b-98b2-5075-8c25-53fcdb7ccc0a'::uuid, 2, 'calc', 'Marta tem R$ 10.000: 60% num CDB que rendeu 10% no ano e 40% num fundo que perdeu 5%. Qual foi o resultado total, em reais?', '{"unit": "R$"}'::jsonb),
('38effd5f-7251-576b-b11d-58488a443370'::uuid, '4c9aba9b-98b2-5075-8c25-53fcdb7ccc0a'::uuid, 3, 'quiz', 'Alguém oferece ''rendimento garantido de 5% ao mês, sem risco'', pedindo PIX para uma pessoa física. O que fazer?', '{"opts": ["Investir pouco para testar", "Desconfiar: retorno alto, garantido e sem risco é sinal clássico de golpe; verificar a autorização na CVM", "Investir, porque 5% ao mês é ótimo", "Pedir para um amigo investir primeiro"]}'::jsonb)
insert into private.education_answer_keys (activity_id, answer, expected_text, explanation) values
('afeeefce-155f-5362-a69b-b1bf90b43e9b'::uuid, '1'::jsonb, 'Os dois estão poupando, mas só Beto está investindo', 'Poupar é separar o dinheiro; os dois fazem isso. Investir é aplicar em um produto financeiro, o que só Beto fez.'),
('e12bd45b-fff1-5b35-b689-9ee509b9e145'::uuid, '[0, 1, 1, 0, 1, 0]'::jsonb, 'Separar 10% da mesada assim que recebe: Hábito de poupar; Caderneta de poupança: Produto financeiro; Tesouro Selic: Produto financeiro; Deixar de pedir delivery e guardar a diferença: Hábito de poupar; CDB: Produto financeiro; Guardar o troco do lanche num cofrinho: Hábito de poupar', 'Atitudes de separar dinheiro são hábitos. Caderneta, Tesouro Selic e CDB são produtos onde o dinheiro separado pode ficar.'),
('ad476c6b-5e37-570f-8f2e-503cb33358cb'::uuid, '[0, 2, 4]'::jsonb, 'A caderneta é um produto financeiro, não sinônimo de poupar; Todo produto tem rendimento, liquidez e risco próprios; Guardar dinheiro sem aplicar também é poupar', 'Poupar é o hábito; a caderneta é só um dos produtos. Ela pode, sim, render menos que a inflação em alguns períodos.'),
('3b5c9fc9-2826-50af-9461-7f7110242cd3'::uuid, '[0, 2, 4]'::jsonb, 'Conserto urgente do celular que você usa para estudar; Perda temporária de renda; Remédio que não estava previsto', 'Reserva é para imprevistos e necessidades urgentes. Promoções, lançamentos e lazer são desejos: podem esperar ou virar uma meta.'),
('f89c0b4f-1244-56ac-b83f-ef8af9d543c3'::uuid, '4500'::jsonb, 'R$ 4.500,00', 'Lazer não entra: 700 + 450 + 150 + 200 = 1.500 por mês de gastos essenciais; 1.500 × 3 = 4.500.'),
('517af18e-13b9-50ff-bb77-cf6665a01781'::uuid, '9'::jsonb, '9 meses', 'Faltam 4.500 − 1.800 = 2.700. Com R$ 300 por mês: 2.700 ÷ 300 = 9 meses.'),
('719c9496-1d78-5c1e-b1d7-76b1cc9b774f'::uuid, '1'::jsonb, 'Em um investimento de baixo risco e resgate rápido, como Tesouro Selic ou CDB com liquidez diária', 'Num imprevisto o dinheiro precisa estar disponível e sem grandes perdas. Ações oscilam, prazos longos travam o dinheiro e empréstimos informais podem não voltar.'),
('e069aa5e-80bf-5a56-96bf-69a35e4c1029'::uuid, '1440'::jsonb, 'R$ 1.440,00', '15% de 800 = 120 por mês; 120 × 12 = 1.440.'),
('bcab4376-dce7-5d70-87b5-1277ac71ed39'::uuid, '180'::jsonb, 'R$ 180,00', 'A diferença é 35 − 20 = 15 por semana; 15 × 12 = 180. Repare que a pergunta é a diferença, não o total.'),
('79e5fa89-23b4-5e49-8033-153641cb0214'::uuid, '1'::jsonb, 'B: guarda R$ 360 contra R$ 200, porque separar primeiro não depende de sobrar', 'A guardou 2 × 100 = 200; B guardou 6 × 60 = 360. Um valor menor e constante venceu um valor maior e incerto.'),
('6333e127-3074-50e9-a078-700c306afb80'::uuid, '[0, 1, 0, 1, 0, 1]'::jsonb, 'Transferência automática no dia do pagamento: Ajuda a manter o hábito; Guardar só o que sobrar no fim do mês: Atrapalha o hábito; Ajustar o valor quando a renda muda: Ajuda a manter o hábito; Esperar juntar um valor alto para começar: Atrapalha o hábito; Ter uma meta com valor e prazo: Ajuda a manter o hábito; Usar o dinheiro guardado em compras por impulso: Atrapalha o hábito', 'Automatizar, ajustar e ter um objetivo sustentam o hábito. Depender da sobra, adiar o começo e mexer no guardado sem motivo o enfraquecem.'),
('52bbe383-ffc3-5e79-bc8d-b412d0efc8f2'::uuid, '[0, 1, 0, 1, 0, 1]'::jsonb, 'Mesada: Receita; Passagem de ônibus: Despesa; Venda de bolo: Receita; Assinatura de streaming: Despesa; Dinheiro recebido de presente: Receita; Parcela do celular: Despesa', 'Entrou dinheiro: receita. Saiu dinheiro: despesa — inclusive a parcela de uma compra feita antes.'),
('59045f56-a9d7-5d95-b886-d44243867499'::uuid, '120'::jsonb, 'R$ 120,00', 'Receitas: 300 + 180 = 480. Despesas: 120 + 90 + 150 = 360. Resultado: 480 − 360 = 120.'),
('ea62b563-8d22-5f0f-96e1-dc2cda778851'::uuid, '[0, 1, 0, 1, 0, 1]'::jsonb, 'Mensalidade do curso de inglês: Gasto fixo; Lanches na escola: Gasto variável; Assinatura de streaming: Gasto fixo; Cinema com amigos: Gasto variável; Plano de celular: Gasto fixo; Presentes de aniversário: Gasto variável', 'Fixos se repetem com valor parecido todo mês (mensalidades, assinaturas, planos). Variáveis mudam conforme o uso.'),
('09db1230-2dce-597c-99f9-208d4f696396'::uuid, '[0, 0, 1, 1, 0, 1]'::jsonb, 'Material escolar: Necessidade; Passagem para ir à escola: Necessidade; Jogo novo em lançamento: Desejo; Tênis de marca só por moda: Desejo; Conta de luz: Necessidade; Trocar um celular que ainda funciona bem: Desejo', 'Necessidades são essenciais; desejos podem esperar. A fronteira varia de pessoa para pessoa, o importante é pensar antes de gastar.'),
('060f378f-4602-56c6-afbe-6b0904c5e2f7'::uuid, '[1, 3, 4]'::jsonb, 'Comprei com pressa, por causa de uma promoção ''só hoje''; Comprei para me sentir melhor na hora, sem pensar; Parcelei sem somar as parcelas que já tinha no mês', 'Pressa, emoção e parcelar sem fazer a conta são sinais. Planejar, comparar e esperar 24 horas são o oposto.'),
('2166148d-bca5-589d-9212-6d1c2f035db1'::uuid, '40'::jsonb, 'R$ 40,00', 'Parcelado: 10 × 24 = 240. À vista: 200. A diferença é 240 − 200 = 40 — o ''sem juros'' escondia um preço maior.'),
('179a914a-87f7-5188-a0da-b79bc1b5c061'::uuid, '1'::jsonb, 'Comprar a mochila e planejar o tênis para quando couber no orçamento', 'A mochila é necessidade; o tênis é desejo com pressão de promoção. Parcelar os dois compromete os próximos meses, e deixar a necessidade sem resolver também não ajuda.'),
('75432aa2-175b-58c0-916d-21279e6c180f'::uuid, '[0, 1, 2, 0, 1, 2]'::jsonb, 'Anotar o lanche no app logo depois de pagar: Registrar; Marcar a compra do caderno como Educação: Categorizar; Comparar o gasto de lazer com o planejado no fim do mês: Revisar; Lançar o valor da passagem de ônibus: Registrar; Separar os gastos do mês entre fixos e variáveis: Categorizar; Decidir reduzir o delivery no mês seguinte: Revisar', 'Registrar é anotar cada valor; categorizar é dar um grupo a ele; revisar é comparar e decidir o que muda.'),
('4015f9de-3893-5307-ac68-9309f85d80e1'::uuid, '60'::jsonb, 'R$ 60,00', 'Planejado: 100 + 120 + 250 = 470. Gasto: 150 + 110 + 270 = 530. Passou 530 − 470 = 60.'),
('3b33925d-a504-5a9a-976d-6bcb3db22f94'::uuid, '1'::jsonb, 'Rever o lazer, que passou R$ 50 do planejado e explica a maior parte do excesso', 'Transporte ficou R$ 10 abaixo; alimentação passou R$ 20; lazer passou R$ 50. O maior desvio é o primeiro lugar para olhar.'),
('5c3f5a63-6691-5345-95f5-e9e136a94177'::uuid, '47'::jsonb, '47%', 'Sobrou 1.000 − 530 = 470. 470 ÷ 1.000 = 0,47, ou seja, 47%.'),
('56a32696-fd0c-566c-867d-d3d1f107bfc4'::uuid, '2100'::jsonb, 'R$ 2.100,00', '3.000 − 900 = 2.100.'),
('474397f3-5671-5185-abeb-4a39c0e822f7'::uuid, '350'::jsonb, 'R$ 350,00', 'Ele guarda em 7 − 1 = 6 meses: 2.100 ÷ 6 = 350. Planejar com os meses reais evita ficar para trás.'),
('89367997-3379-521c-952e-63468a8f3d59'::uuid, '[0, 1, 2, 1, 0]'::jsonb, 'Presente de aniversário daqui a 2 meses: Curto prazo; Notebook daqui a 2 anos: Médio prazo; Entrada da faculdade daqui a 8 anos: Longo prazo; Viagem de formatura daqui a 3 anos: Médio prazo; Passeio no mês que vem: Curto prazo', 'Uma referência: até 1 ano é curto, de 1 a 5 é médio e acima de 5 é longo.'),
('82c6e5d5-afd3-500a-b6ca-bcd96ce2da26'::uuid, '1'::jsonb, 'Quero juntar R$ 1.200 para um curso até dezembro, guardando R$ 150 por mês', 'Só a segunda tem objetivo, valor, prazo e contribuição mensal. As outras não permitem saber se você está no caminho.'),
('08d6dd3f-932e-503f-85df-e494b748bf45'::uuid, '{"sum": 100, "min": {"2": 15}, "max": {"0": 55, "1": 30}}'::jsonb, 'Distribuições possíveis: 50% / 30% / 20% ou 55% / 30% / 15%.', 'Vários planos servem, desde que fechem 100% e respeitem os três limites. A 50/30/20 é só um ponto de partida.'),
('cb06908d-860f-52d0-a151-45a1e648e57c'::uuid, '240'::jsonb, 'R$ 240,00', 'Poupança: 20% de 1.200 = 240. Desejos: 1.200 − 720 − 240 = 240.'),
('b93f423b-02f5-556d-a80c-0dd8173f7dd8'::uuid, '1'::jsonb, '60%: acima da referência de 50%, então vale rever gastos essenciais ou aceitar menos desejos', '720 ÷ 1.200 = 0,6, ou seja, 60%. Acima de 50%, algo precisa ceder para manter a poupança.'),
('a55cf097-5624-5fef-bf18-73669242829b'::uuid, '1'::jsonb, 'O governo federal', 'Os títulos são públicos, emitidos pelo governo federal.'),
('1cc22d36-c880-5133-b9b2-5ab10568ebcf'::uuid, '[0, 1, 2, 0, 2]'::jsonb, 'Rende de acordo com a taxa básica de juros: Tesouro Selic; Você sabe a taxa exata no momento da compra: Tesouro Prefixado; Paga a inflação do período mais uma taxa: Tesouro IPCA+; Costuma ser usado para reserva de emergência, por oscilar pouco: Tesouro Selic; Protege o poder de compra em objetivos longos: Tesouro IPCA+', 'Selic: segue os juros básicos e oscila pouco. Prefixado: taxa travada na compra. IPCA+: inflação mais uma taxa, pensado para o longo prazo.'),
('26791cfb-5a5e-55e9-b74b-5d67eb531c3f'::uuid, '1'::jsonb, 'Pode render menos ou mais, conforme o preço do título no dia da venda', 'A taxa combinada só é garantida se você levar até o vencimento. Antes disso, vale o preço de mercado do dia.'),
('0f3cabe3-313d-5bc1-9895-aec0fd7c6f65'::uuid, '0'::jsonb, 'O Copom, do Banco Central', 'O Copom se reúne periodicamente e define a meta da Selic.'),
('3ae57711-5c56-5c14-bcca-b1dcd2a7fcad'::uuid, '121'::jsonb, 'R$ 121,00', 'Ano 1: 110. Ano 2: 110 × 1,10 = 121. Os juros do segundo ano incidem sobre 110, não sobre 100.'),
('d26572e5-d868-5c12-ae5c-467347b1a1a0'::uuid, '6'::jsonb, '6%', '10 − 4 = 6. O saldo cresceu 10%, mas como os preços subiram 4%, o poder de compra cresceu cerca de 6%.'),
('3e404291-53f5-50e2-bf51-25228b8ebba4'::uuid, '1'::jsonb, 'Perdeu cerca de 1% de poder de compra, mesmo com saldo maior', '5 − 6 = −1. O número na conta subiu, mas os preços subiram mais: dá para comprar um pouco menos do que antes.'),
('f87652e7-2781-576d-8124-eeaf90dac7b8'::uuid, '1'::jsonb, 'As cotas podem oscilar e o rendimento pode variar', 'Preço e rendimento variam. Não existe garantia de retorno.'),
('5e73c233-edf3-53eb-8ea1-b35d50806e75'::uuid, '[0, 1, 3]'::jsonb, 'Queda no preço da cota; Imóveis vagos reduzirem os rendimentos; Não conseguir vender a cota rápido pelo preço desejado', 'Preço, vacância e liquidez são riscos reais. Não existe garantia do FGC para fundos, nem rendimento fixo combinado.'),
('f77ad52a-2434-5f76-8836-5d52532d5b57'::uuid, '1.6'::jsonb, 'R$ 1,60', 'Rendimentos: 0,80 × 12 = 9,60. Variação da cota: 92 − 100 = −8,00. Resultado: 9,60 − 8,00 = 1,60.'),
('bc1ec29f-9974-5781-8587-8bf301404e97'::uuid, '0'::jsonb, 'Maior retorno esperado costuma vir com maior risco', 'Quanto maior o retorno que se espera, em geral maior o risco assumido.'),
('ba892358-4119-52dd-9b2f-47590773c7b6'::uuid, '[0, 2, 3, 5]'::jsonb, 'Comparar liquidez e prazo; Conferir custos e tributação; Diversificar; Verificar se a instituição é autorizada pela CVM ou pelo Banco Central', 'Desconfie de lucro garantido e de rentabilidade passada como promessa. Compare prazo, custos e tributação, diversifique e confira a autorização da instituição.'),
('0b61b54b-6f83-5103-b902-1541d51ab8e5'::uuid, '[0, 1, 0, 1, 0]'::jsonb, 'Reserva de emergência: Resgate rápido e baixo risco; Aposentadoria daqui a 30 anos: Prazo longo, pode oscilar; Conserto que pode surgir a qualquer momento: Resgate rápido e baixo risco; Entrada de um imóvel daqui a 10 anos: Prazo longo, pode oscilar; Viagem do mês que vem: Resgate rápido e baixo risco', 'Dinheiro que pode ser necessário logo pede liquidez e pouco risco. Objetivos distantes aguentam oscilações em busca de mais retorno.'),
('9b8e9045-1d5e-5068-9c8b-207aa6aafbc4'::uuid, '400'::jsonb, 'R$ 400,00', 'CDB: 6.000 × 10% = +600. Fundo: 4.000 × (−5%) = −200. Total: 600 − 200 = 400. Diversificar reduziu o impacto da perda.'),
('38effd5f-7251-576b-b11d-58488a443370'::uuid, '1'::jsonb, 'Desconfiar: retorno alto, garantido e sem risco é sinal clássico de golpe; verificar a autorização na CVM', 'Não existe retorno alto garantido sem risco. Pagamento para pessoa física e pressa são outros alertas.')
